#include "PluginEditor.h"
DISidechainEditor::DISidechainEditor(DISidechainProcessor& p):AudioProcessorEditor(&p),proc(p){
 const char* ids[]={"depth","mix","threshold","length","smooth","low","high","retrigger"};
 const char* names[]={"DEPTH","MIX","THRESHOLD","LENGTH MS","SMOOTH MS","LOW HZ","HIGH HZ","HOLDOFF MS"};
 for(int i=0;i<8;++i){auto s=std::make_unique<juce::Slider>();s->setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s->setTextBoxStyle(juce::Slider::TextBoxBelow,false,95,19);s->setColour(juce::Slider::rotarySliderFillColourId,juce::Colour(0xffff6969));auto l=std::make_unique<juce::Label>();l->setText(names[i],juce::dontSendNotification);l->setJustificationType(juce::Justification::centred);l->setColour(juce::Label::textColourId,juce::Colours::lightgrey);addAndMakeVisible(*s);addAndMakeVisible(*l);sa.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],*s));sliders.push_back(std::move(s));labels.push_back(std::move(l));}
 const char* cids[]={"mode","trigger","division"};const juce::StringArray choices[]={ {"Full","Low","High","Band"},{"Audio + MIDI","Audio only","MIDI only"},{"1/32","1/16","1/8","1/4","1/2","1 bar","2 bars"}};
 for(int i=0;i<3;++i){auto c=std::make_unique<juce::ComboBox>();c->addItemList(choices[i],1);addAndMakeVisible(*c);ca.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,cids[i],*c));combos.push_back(std::move(c));}
 sync=std::make_unique<juce::ToggleButton>("Tempo sync");addAndMakeVisible(*sync);ba=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"sync",*sync);sequenceToggle=std::make_unique<juce::ToggleButton>("SHAPE SEQUENCER");addAndMakeVisible(*sequenceToggle);sequenceAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"sequenceEnabled",*sequenceToggle);
 sequenceCount=std::make_unique<juce::Slider>(juce::Slider::LinearHorizontal,juce::Slider::TextBoxRight);sequenceCount->setRange(1,32,1);addAndMakeVisible(*sequenceCount);sequenceCountAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,"sequenceSteps",*sequenceCount);
 setSize(1000,630);startTimerHz(25);
}
void DISidechainEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff11151e));g.setColour(juce::Colours::white);g.setFont(juce::FontOptions(27.f,juce::Font::bold));g.drawText("DI SIDECHAIN",24,14,350,45,juce::Justification::centredLeft);g.setColour(juce::Colour(0xffff6969));g.fillRect(24,62,getWidth()-48,2);
 g.setColour(juce::Colour(0xff1b2330));g.fillRoundedRectangle(graph.toFloat(),9);g.setColour(juce::Colour(0xff354151));for(int i=0;i<=7;++i){float x=graph.getX()+graph.getWidth()*i/7.f;g.drawVerticalLine((int)x,(float)graph.getY(),(float)graph.getBottom());}for(int i=0;i<=4;++i){float y=graph.getY()+graph.getHeight()*i/4.f;g.drawHorizontalLine((int)y,(float)graph.getX(),(float)graph.getRight());}
 juce::Path path;for(int i=0;i<8;++i){float x=graph.getX()+graph.getWidth()*i/7.f,y=graph.getBottom()-(sequenceToggle->getToggleState()?proc.getSequencePoint(selectedStep,i):proc.points[i].load())*graph.getHeight();if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour(juce::Colour(0xffff6969));g.strokePath(path,juce::PathStrokeType(3));for(int i=0;i<8;++i){float x=graph.getX()+graph.getWidth()*i/7.f,y=graph.getBottom()-proc.points[i].load()*graph.getHeight();g.setColour(juce::Colours::white);g.fillEllipse(x-5,y-5,10,10);}
 const int count=juce::jlimit(1,32,(int)sequenceCount->getValue());
 const int playing=proc.activeSequenceStep.load(std::memory_order_relaxed);
 for(int i=0;i<count;++i){auto cell=juce::Rectangle<float>((float)stepStrip.getX()+i*stepStrip.getWidth()/(float)count,(float)stepStrip.getY(),stepStrip.getWidth()/(float)count-2.f,(float)stepStrip.getHeight());g.setColour(i==selectedStep?juce::Colour(0xfffa9a43):i==playing&&sequenceToggle->getToggleState()?juce::Colour(0xffb3ff4c):juce::Colour(0xff283444));g.fillRoundedRectangle(cell,3.f);}
 g.setColour(juce::Colours::lightgrey);g.setFont(14);g.drawText(sequenceToggle->getToggleState()?"STEP "+juce::String(selectedStep+1)+"  -  drag nodes to edit":"ENVELOPE  -  drag nodes to edit  -  0 = silence, 1 = unity",graph.getX(),graph.getY()-28,graph.getWidth(),24,juce::Justification::centredLeft);g.drawText("FREQUENCY MODE",24,432,180,20,juce::Justification::centredLeft);g.drawText("TRIGGER SOURCE",264,432,180,20,juce::Justification::centredLeft);g.drawText("TEMPO DIVISION",504,432,180,20,juce::Justification::centredLeft);
}
void DISidechainEditor::resized(){graph={24,105,juce::jmax(1,getWidth()-48),220};stepStrip={24,343,juce::jmax(1,getWidth()-48),28};if(sequenceToggle)sequenceToggle->setBounds(24,385,180,28);if(sequenceCount)sequenceCount->setBounds(210,385,180,28);if(sliders.size()!=8||labels.size()!=8||combos.size()!=3||sync==nullptr)return;for(int i=0;i<8;++i){int x=16+i*103;labels[i]->setBounds(16+i*(getWidth()-32)/8,526,(getWidth()-32)/8,20);sliders[i]->setBounds(16+i*(getWidth()-32)/8,546,(getWidth()-32)/8,80);}for(int i=0;i<3;++i)combos[i]->setBounds(24+i*240,458,215,29);sync->setBounds(770,458,180,29);}
void DISidechainEditor::updatePoint(const juce::MouseEvent& e){if(!graph.contains(e.getPosition()))return;int i=juce::jlimit(0,7,juce::roundToInt((e.position.x-graph.getX())/graph.getWidth()*7.f));const float v=juce::jlimit(0.f,1.f,(graph.getBottom()-e.position.y)/graph.getHeight());if(sequenceToggle->getToggleState())proc.setSequencePoint(selectedStep,i,v);else proc.points[i]=v;repaint();}
void DISidechainEditor::mouseDown(const juce::MouseEvent& e){if(stepStrip.contains(e.getPosition())){const int count=juce::jlimit(1,32,(int)sequenceCount->getValue());selectedStep=juce::jlimit(0,count-1,(e.getPosition().x-stepStrip.getX())*count/juce::jmax(1,stepStrip.getWidth()));repaint();return;}updatePoint(e);}
void DISidechainEditor::mouseDrag(const juce::MouseEvent& e){updatePoint(e);}
